In this paper, we develop and analyze a family of model-based methods,
moving beyond naive stochastic gradient methods, for solving the stochastic
convex optimization problem
\begin{equation}
  \label{eqn:objective}
  \begin{split}
    \minimize ~ & F(x) = \E_P[f(x;\statrv)]
    = \int_\statdomain f(x; \statval) dP(\statval) \\
    \subjectto ~ & x \in \mc{X}.
  \end{split}
\end{equation}
In problem~\eqref{eqn:objective}, the set $\statdomain$ is a sample space,
and for each $\statval \in \statdomain$, the function $f(\cdot; \statval) :
\R^n \to \R$ is a closed convex function, subdifferentiable
on the closed convex set $\mc{X} \subset \R^n$.


We show how to extend this modeling perspective to stochastic convex
optimization problems, leveraging it to build a new family of algorithms for
solving problem~\eqref{eqn:objective}, which, in homage to the stochastic
proximal point iteration~\eqref{eqn:sppm}, we call the \aProx (approximate
proximal point) algorithms, with substantially better theoretical guarantees
and empirical performance than naive stochastic subgradient methods. The
\aProx algorithms iterate as follows: for $k = 1, 2, \ldots$, we draw a
random $\statrv_k \simiid P$, then update the iterate $x_k$ by minimizing a
regularized approximation to $f(\cdot; \statrv_k)$, setting
\begin{equation}
  \label{eqn:model-iteration}
  x_{k+1} \defeq \argmin_{x \in \mc{X}}
  \left\{ f_{x_k}(x ; \statrv_k) + \frac{1}{2 \stepsize_k}
  \ltwo{x - x_k}^2 \right\}.
\end{equation}
The function $f_x(\cdot ; \statval)$ is a \emph{model} of $f(\cdot;
\statval)$ at the point $x$, meaning that $f_x$ satisfies the
following conditions on its structure and local approximation
properties for $f$:
\begin{enumerate}[label=(C.\roman*),leftmargin=*]
\item \label{cond:convex-model}
  The function $y \mapsto f_x(y; \statval)$ is convex
  and subdifferentiable on $\mc{X}$.
\item \label{cond:lower-model}
  The model $f_x$ satisfies the equality
  $f_x(x; \statval) = f(x; \statval)$ and
  \begin{equation*}
    f_x(y; \statval) \le f(y; \statval) ~~ \mbox{for~all~} y.
  \end{equation*}
%\item \label{cond:subgrad-model}
%  At $y = x$, we have the containment
%  \begin{equation*}
%    \left.\partial_y f_x(y; \statval)\right|_{y = x}
%    \subset \partial_x f(x; \statval).
%  \end{equation*}
\end{enumerate}
\noindent
By the first-order conditions for convexity, for any $g \in \partial_y
f_x(y; \statval)|_{y=x}$ Conditions~\ref{cond:convex-model}
and~\ref{cond:lower-model} imply $f(y; \statval) \ge f_x(y; \statval) \ge
f_x(x; \statval) + \<g, y - x\> = f(x; \statval) + \<g, y - x\>$, yielding
the containment
\begin{equation}
  \label{eqn:subgrad-containment}
  \left.\partial_y f_x(y; \statval)\right|_{y = x}
  \subset \partial_x f(x; \statval).
\end{equation}


\begin{assumption}
  \label{assumption:convex}
  The set $\mc{X}\opt \defeq \argmin_{x \in \mc{X}} \{F(x)\}$ is non-empty,
  and there exists $\sigma^2 < \infty$
  such that $\E[\ltwo{f'(x\opt;\statrv)}^2] \leq \sigma^2$
  for $x\opt \in \mc{X}\opt$ 
  and all measurable selections $f'(x\opt; \statval) \in \partial
  f(x\opt; \statval)$.
\end{assumption}

\begin{assumption}
  \label{assumption:very-weak-moment}
  There exists a non-decreasing function $\growfunc : \R_+ \to
  \openright{0}{\infty}$ such that for all $x \in
  \mc{X}$ and measurable selections $f'(x; \statval) \in \partial
  f(x; \statval)$,
  $\E[\norm{f'(x; \statrv)}^2] \le \growfunc(\dist(x, \mc{X}\opt))$.
\end{assumption}


\paragraph{Notation}
For a convex function $f$, $\partial f(x)$ denotes its subgradient set at
$x$, and $f'(x) \in \partial f(x)$ denotes an arbitrary element of
the subdifferential.  Throughout, $x\opt$ denotes a minimizer of
problem~\eqref{eqn:objective} and $\mc{X}\opt = \argmin_{x \in \mc{X}} F(x)$
its optimal set.  We let $\mc{F}_k \defeq \sigma(\statrv_1, \ldots,
\statrv_k)$ be the $\sigma$-field generated by the first $k$ random
variables $\statrv_i$, so $x_k \in
\mc{F}_{k-1}$ for all $k$ under iteration~\eqref{eqn:model-iteration}.


\begin{lemma}[\cite{RobbinsSi71}]
  \label{lemma:robbins-siegmund}
  Let $A_k, B_k, C_k, D_k \ge 0$ be non-negative random variables adapted to
  the filtration $\mc{F}_k$ and satisfying $\E[A_{k + 1} \mid \mc{F}_k] \le
  (1 + B_k) A_k + C_k - D_k$. Then on the event $\{\sum_k B_k < \infty,
  \sum_k C_k < \infty\}$, there is a random $A_\infty < \infty$
  such that $A_k \cas A_\infty$ and $\sum_k D_k < \infty$.
\end{lemma}


The key consequence of Theorem~\ref{theorem:prox-point-bounded} is that the
iterates $x_k$ are stable in probability~\eqref{eqn:bounded-distance},
remaining bounded with probability 1. Iterate boundedness of algorithms does
not guarantee convergence in general; however, in this section, we show that
as a consequence of this boundedness, any algorithm satisfying
Conditions~\ref{cond:convex-model}--\ref{cond:lower-model} is convergent.
Assumptions~\ref{assumption:convex}
and~\ref{assumption:very-weak-moment} are insufficient to guarantee
convergence of subgradient methods, which---as our examples show---may
diverge without uniform boundedness conditions on the subgradients.  In
contrast, any \aProx method that is stable in
probability~\eqref{eqn:bounded-distance} guarantees convergence with
probability 1.  Throughout this section and
Section~\ref{sec:asymptotic-normality}, we without comment make the
assumption that the stepsizes $\stepsize_k$ satisfy the standard summability
conditions
\begin{equation*}
  \stepsize_k > 0 ~ \mbox{for~all~} k,
  ~~~
  \sum_{k=1}^\infty \stepsize_k = \infty,
  ~~~ \mbox{and} ~~~
  \sum_{k=1}^\infty \stepsize_k^2 < \infty.
\end{equation*}

